# Let's re-run the script and see the results.
def get_max_for_N(N):
    import itertools
    max_val = 0
    for path in itertools.product(['A', 'B'], repeat=N):
        best_path_sum = 0
        # Let's try more values of x0.
        # The optimal x0 for a given path will likely be at the boundary x_N = x_0
        # or at a point where the derivative of the sum is 0.
        # The sum is a polynomial in x_0.
        for x0 in [i/2000 for i in range(2001)]:
            curr_x = x0
            curr_sum = 0
            for step in path:
                if step == 'A':
                    curr_sum += curr_x
                    curr_x = 4 * curr_x**2
                else:
                    curr_sum += 0.25 - curr_x
                    curr_x = curr_x / 2
            if curr_x <= x0:
                if curr_sum > best_path_sum:
                    best_path_sum = curr_sum
        max_val = max(max_val, best_path_sum)
    return max_val

for n in range(1, 6):
    print(f"N={n}, max={get_max_for_N(n)}")
